style.css:
@-moz-document domain("open.spotify.com") {
/* Force background on core layout wrappers */
  html, body, #main, [class*="Root"], [class*="Layout"] {
    background: url('https://i.pinimg.com/736x/87/42/1d/87421d031e05a81e3a1f8615b3c5305a.jpg') no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Make default panels transparent */
  [data-testid="root"], 
  main, 
  nav, 
  aside, 
  div[class*="main-view-container"] {
    background-color: transparent !important;
    background-image: none !important;
  }

  /* Apply glass effect to main containers */
  main, nav, aside {
    background: rgba(255, 255, 255, 0.2) !important;
    backdrop-filter: blur(12px) !important;
    border-radius: 8px !important;
  }

  /* Floating Clownfish */
  body::before {
    content: "";
    position: fixed;
    top: 20px;
    right: 180px;
    width: 60px;
    height: 60px;
    background: url('https://64.media.tumblr.com/d7042e129b967b23103ac860a34f2587/e151e690f0ca9ec8-6f/s100x100/tumblr_d7042e129b967b23103ac860a34f2587_e151e690_100.png') no-repeat center/contain !important;
    pointer-events: none;
    z-index: 99999;
  }

  /* Floating Planet */
  body::after {
    content: "";
    position: fixed;
    bottom: 110px;
    left: 20px;
    width: 50px;
    height: 50px;
    background: url('https://64.media.tumblr.com/3a9e4878370aab9d456574cd2a843112/aaf2329b359f1f0a-6c/s100x100/tumblr_3a9e4878370aab9d456574cd2a843112_aaf2329b_75.webp') no-repeat center/contain !important;
    pointer-events: none;
    z-index: 99999;
  }
}
